@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@500;600;700;800&family=Inter:wght@400;500;600&display=swap');

:root {
  --bg: #f5f2ed;
  --text: #1a1a1a;
  --muted: #5d5954;
  --line: #d9d2c9;
  --accent-terracotta: #c98773;
  --accent-sage: #8f9d86;
  --accent-sand: #d1b697;
  --accent-clay: #b99887;
  --content-max: 1260px;
  --reading-max: 760px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
}

body {
  font-family: 'Inter', sans-serif;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

a {
  color: inherit;
  text-decoration: none;
}

a:focus-visible,
button:focus-visible {
  outline: 2px solid var(--text);
  outline-offset: 3px;
}

.site-shell {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.container {
  width: min(var(--content-max), calc(100% - 4rem));
  margin: 0 auto;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 20;
  backdrop-filter: blur(8px);
  background: color-mix(in srgb, var(--bg) 92%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--line) 65%, transparent);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 76px;
}

.brand {
  font-family: 'Playfair Display', serif;
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.01em;
}

.nav-desktop {
  display: flex;
  gap: 1.75rem;
  font-size: 0.94rem;
}

.nav-desktop a {
  color: var(--muted);
}

.nav-desktop a[aria-current='page'] {
  color: var(--text);
}

.menu-toggle {
  display: none;
  width: 44px;
  height: 44px;
  border: 0;
  background: transparent;
  position: relative;
  cursor: pointer;
}

.menu-toggle span,
.menu-toggle::before,
.menu-toggle::after {
  content: '';
  display: block;
  position: absolute;
  left: 10px;
  right: 10px;
  height: 1.5px;
  background: var(--text);
  transition: transform 220ms ease, opacity 220ms ease;
}

.menu-toggle span { top: 21px; }
.menu-toggle::before { top: 14px; }
.menu-toggle::after { top: 28px; }

.menu-toggle[aria-expanded='true'] span { opacity: 0; }
.menu-toggle[aria-expanded='true']::before { transform: translateY(7px) rotate(45deg); }
.menu-toggle[aria-expanded='true']::after { transform: translateY(-7px) rotate(-45deg); }

.mobile-menu {
  position: fixed;
  inset: 0;
  background: var(--bg);
  display: grid;
  place-items: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 260ms ease;
  z-index: 50;
}

.mobile-menu.open {
  opacity: 1;
  pointer-events: auto;
}

.mobile-menu nav {
  display: flex;
  flex-direction: column;
  gap: 1.4rem;
  text-align: center;
}

.mobile-menu a {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2rem, 8vw, 3.5rem);
}

.kicker {
  font-size: 0.83rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.hero-title,
.page-title,
.contact-title {
  font-family: 'Playfair Display', serif;
  font-weight: 700;
  line-height: 0.95;
  letter-spacing: -0.02em;
}

.hero-title { font-size: clamp(2.8rem, 8vw, 7rem); }
.page-title { font-size: clamp(2.4rem, 7vw, 5.3rem); margin: 0; }

.section {
  padding: clamp(4rem, 8vw, 8rem) 0;
}

.split-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: clamp(2rem, 5vw, 5.5rem);
  align-items: start;
}

.lead {
  font-size: clamp(1.06rem, 1.6vw, 1.34rem);
  color: color-mix(in srgb, var(--text) 90%, var(--muted));
  max-width: 36ch;
}

.placeholder-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 1rem;
  margin-top: 2rem;
}

.placeholder {
  border-radius: 2px;
  min-height: 130px;
}

.placeholder.tall { grid-column: span 2; min-height: 300px; }
.placeholder.wide { grid-column: span 4; min-height: 180px; }

.marquee-section {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 2.2rem 0;
  overflow: hidden;
}

.marquee-row {
  display: flex;
  width: max-content;
  white-space: nowrap;
  will-change: transform;
  margin: 0.75rem 0;
  font-size: clamp(1.2rem, 2.2vw, 2rem);
  font-family: 'Playfair Display', serif;
}

.marquee-row span {
  display: inline-block;
  padding-right: 2.6rem;
}

.about-layout,
.letter-layout {
  display: grid;
  grid-template-columns: 280px minmax(0, var(--reading-max));
  gap: clamp(2rem, 6vw, 6rem);
  align-items: start;
}

.aside-note {
  font-size: 0.88rem;
  color: var(--muted);
  position: sticky;
  top: 112px;
}

.reading {
  font-size: 1.1rem;
  line-height: 1.85;
}

.reading p { margin: 0 0 1.65rem; }

.reading .large-drop {
  font-family: 'Playfair Display', serif;
  font-size: 1.22em;
}

.services-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.2rem;
  margin-top: 2rem;
}

.service-card {
  border: 1px solid var(--line);
  padding: 1.4rem;
}

.service-card h3 {
  font-family: 'Playfair Display', serif;
  font-size: 1.55rem;
  margin: 0 0 0.65rem;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.5rem 2rem;
  margin-top: 2.8rem;
}

.client-item h3 {
  margin: 0;
  font-family: 'Playfair Display', serif;
  font-size: 1.65rem;
  line-height: 1.05;
}

.client-item p {
  margin: 0.55rem 0 0;
  color: var(--muted);
  font-size: 0.95rem;
}

.contact-hero {
  min-height: calc(100vh - 78px);
  display: grid;
  align-content: center;
}

.contact-title {
  font-size: clamp(5rem, 19vw, 15rem);
  margin: 0;
}

.contact-links {
  display: flex;
  flex-wrap: wrap;
  gap: 1.2rem 2rem;
  margin-top: 1.3rem;
}

.contact-links a {
  font-size: clamp(1.1rem, 2.2vw, 1.5rem);
  color: var(--muted);
}

.site-footer {
  border-top: 1px solid var(--line);
  margin-top: auto;
}

.footer-inner {
  display: flex;
  justify-content: space-between;
  padding: 1.2rem 0;
  color: var(--muted);
  font-size: 0.86rem;
}

@media (max-width: 1060px) {
  .split-grid,
  .about-layout,
  .letter-layout,
  .services-grid,
  .clients-grid {
    grid-template-columns: 1fr;
  }

  .aside-note {
    position: static;
  }
}

@media (max-width: 820px) {
  .container { width: min(var(--content-max), calc(100% - 2.2rem)); }
  .nav-desktop { display: none; }
  .menu-toggle { display: inline-block; }

  .placeholder-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .placeholder.tall,
  .placeholder.wide {
    grid-column: span 1;
    min-height: 150px;
  }

  .footer-inner {
    flex-direction: column;
    gap: 0.4rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}
EOF

